package main

import (
	"fmt"
	"time"
)

type M struct {
	T *time.Time
	U *M
}

//go:noinline
func (m *M) FooNoInline() bool {
	return m.U.T.Before(*m.T)
}
func (m *M) FooInline() bool {
	return m.U.T.Before(*m.T)
}
func main() {
	now := time.Now()
	m := &M{T: &now, U: &M{}}
	fmt.Println("inline:")
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Println("recovered")
			}
		}()
		m.FooInline()
	}()
	fmt.Println("noinline:")
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Println("recovered")
			}
		}()
		m.FooNoInline()
	}()
	// trigger panic and see trace? We'll just panic
	m2 := &M{T: &now, U: &M{}}
	_ = m2
	// force panic without recover to see trace
	// m.FooInline()
}
