import subprocess, json, re
def run_orig(inp, args):
    p=subprocess.run(['./executable']+args, input=inp.encode(), capture_output=True)
    return p.stdout.decode(), p.stderr.decode(), p.returncode
def run_my(inp, args):
    p=subprocess.run(['/tmp/myexe']+args, input=inp.encode(), capture_output=True)
    return p.stdout.decode(), p.stderr.decode(), p.returncode
def norm_err(e):
    return re.sub(r'^\d{4}/\d{2}/\d{2} \d{2}:\d{2}:\d{2} ', '', e)

cases = [
  ('single', json.dumps({'Path':'ex/a','Version':'v1.0.0'})),
  ('update newer', json.dumps({'Path':'ex/a','Version':'v1.0.0','Time':'2020-01-01T00:00:00Z','Update':{'Path':'ex/a','Version':'v1.0.1','Time':'2021-01-01T00:00:00Z'}})),
  ('update older', json.dumps({'Path':'ex/a','Version':'v1.0.0','Time':'2021-01-01T00:00:00Z','Update':{'Path':'ex/a','Version':'v1.0.1','Time':'2020-01-01T00:00:00Z'}})),
  ('replace+update', json.dumps({'Path':'ex/a','Version':'v1.0.0','Time':'2020-01-01T00:00:00Z','Replace':{'Path':'ex/a','Version':'v1.0.1'},'Update':{'Path':'ex/a','Version':'v1.0.2','Time':'2021-01-01T00:00:00Z'}})),
  ('invalid json', 'not json'),
  ('time bad', json.dumps({'Path':'ex/a','Time':'bad'})),
]

ok=True
for name, inp in cases:
    for args in [[], ['-direct'], ['-update'], ['-ci'], ['-style','markdown']]:
        o_out,o_err,o_code=run_orig(inp,args)
        m_out,m_err,m_code=run_my(inp,args)
        o_err_n=norm_err(o_err); m_err_n=norm_err(m_err)
        # for panic, only check code and out
        if 'panic:' in o_err or 'panic:' in m_err:
            if ('panic:' in o_err) != ('panic:' in m_err) or o_code!=m_code or o_out!=m_out:
                print(f'FAIL panic {name} {args}')
                ok=False
            else:
                print(f'PASS panic {name} {args}')
            continue
        if o_out!=m_out or o_err_n!=m_err_n or o_code!=m_code:
            print(f'FAIL {name} {args} out:{o_out==m_out} err:{o_err_n==m_err_n} code:{o_code==m_code}')
            print(f' orig out {o_out!r} my {m_out!r}')
            print(f' orig err {o_err_n!r} my {m_err_n!r}')
            ok=False
        else:
            print(f'PASS {name} {args}')
print('OK' if ok else 'FAIL')
PY"}

